import java.util.Scanner;

public class COVID {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        long k = scanner.nextLong();

        if (k > n - 1) {
            System.out.println(0);
            return;
        }

        int[] fac = new int[n + 1];
        final int mod = 998244353;
        fac[0] = 1;
        for (int i = 1; i <= n; i++) {
            fac[i] = (int) ((long) fac[i - 1] * i % mod);
        }

        int pop = n - (int) k;
        long answer = 0;

        for (int i = 0; i <= pop; i++) {
            long notPop = (nCr(pop, i, fac, mod) * powMod(pop - i, n, mod)) % mod;
            if (i % 2 == 1) {
                notPop = -notPop;
            }
            answer = (answer + notPop + mod) % mod;
        }

        answer = (answer * nCr(n, pop, fac, mod)) % mod;
        if (k != 0) {
            answer = (answer * 2) % mod;
        }
        System.out.println(answer);
    }

    static long powMod(long base, long exp, int mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * base) % mod;
            }
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static long nCr(int n, int r, int[] fac, int mod) {
        long numerator = fac[n];
        long denominator = (long) fac[r] * fac[n - r] % mod;
        return numerator * powMod(denominator, mod - 2, mod) % mod;
    }
}
